"""Intent tests for risk.annualize (PL-02 step 4, RISK-03, TC-06)."""

from __future__ import annotations

import pytest

from risk import Returns, VolSeries, annualize


def returns_of(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def vol_of(payload: dict) -> VolSeries:
    return VolSeries(
        returns=returns_of(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


@pytest.fixture
def tc06(golden):
    data, expected = golden("risk", "TC-06")
    return vol_of(data["vol"]), expected


@pytest.mark.intent
def test_tc06_each_value_is_scaled_within_tolerance(tc06):
    vol, expected = tc06
    result = annualize(vol)
    assert sorted(result.values) == sorted(expected["values"])
    for ticker, want in expected["values"].items():
        got = result.values[ticker]
        assert len(got) == len(want)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, abs=expected["tol"], rel=0)


@pytest.mark.intent
def test_tc06_gaps_are_kept(tc06):
    vol, expected = tc06
    result = annualize(vol)
    for ticker, want in expected["values"].items():
        gaps = [i for i, w in enumerate(want) if w is None]
        assert [i for i, g in enumerate(result.values[ticker]) if g is None] == gaps


@pytest.mark.intent
def test_tc06_result_is_flagged_annualized(tc06):
    vol, expected = tc06
    result = annualize(vol)
    assert result.annualized is expected["annualized"]


@pytest.mark.intent
def test_tc06_returns_and_window_carry_through(tc06):
    vol, _ = tc06
    result = annualize(vol)
    assert result.returns == vol.returns
    assert result.window == vol.window


@pytest.mark.intent
def test_tc06_explicit_252_matches_default(tc06):
    vol, expected = tc06
    result = annualize(vol, periods_per_year=252)
    for ticker, want in expected["values"].items():
        for g, w in zip(result.values[ticker], want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, abs=expected["tol"], rel=0)


@pytest.mark.intent
def test_annualizing_an_annualized_series_is_a_value_error(contract_sample):
    vol = vol_of(contract_sample("risk.VolSeries"))
    assert vol.annualized is True
    with pytest.raises(ValueError, match=r"(?i)annuali[sz]ed"):
        annualize(vol)


@pytest.mark.intent
def test_annualizing_twice_is_a_value_error(tc06):
    vol, _ = tc06
    once = annualize(vol)
    with pytest.raises(ValueError, match=r"(?i)annuali[sz]ed"):
        annualize(once)

